-- [COMP:memory/learning] Additive; NULL is the existing unassessed cohort.
ALTER TABLE memories ADD COLUMN learning jsonb;
ALTER TABLE memories_shadow ADD COLUMN learning jsonb;
ALTER TABLE memories ADD CONSTRAINT memory_learning_shape CHECK (learning IS NULL OR
 (jsonb_typeof(learning)='object' AND learning->>'version'='1'
  AND learning->>'state' IN ('legacy','candidate','established','retired')
  AND jsonb_typeof(learning->'applicability')='object') IS TRUE);
CREATE INDEX memory_learning_candidates ON memories(workspace_id,created_at)
 WHERE valid_to IS NULL AND learning->>'state'='candidate';

-- Captured qualifying groups remain valid only while their original evidence is live.
-- No age cutoff here: the 30-day window gates admission, not established retention.
CREATE FUNCTION memory_learning_evidence_allows(value jsonb) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE evidence_group jsonb; event_count integer; root_count integer;
BEGIN
 IF value IS NULL OR value->'evidenceGroups' IS NULL THEN RETURN true;END IF;
 IF jsonb_typeof(value->'evidenceGroups') IS DISTINCT FROM 'array' THEN RETURN false;END IF;
 FOR evidence_group IN SELECT jsonb_array_elements(value->'evidenceGroups') LOOP
  IF jsonb_typeof(evidence_group) IS DISTINCT FROM 'array' OR jsonb_array_length(evidence_group)=0 THEN RETURN false;END IF;
  SELECT count(DISTINCT e.payload->>'originHash'),count(DISTINCT e.payload->>'root') INTO event_count,root_count
  FROM decision_events e JOIN session_messages m ON m.id::text=e.source_id
  JOIN sessions s ON s.id=m.session_id
  WHERE e.id::text IN(SELECT jsonb_array_elements_text(evidence_group))
   AND e.event_kind='memory.observation_recorded' AND e.created_at<=now()
   AND m.role='user' AND NOT m.scope_held AND s.recording_revision IS NULL AND session_recording_read_allowed(s.id)
   AND (m.sender_user_id=e.actor_user_id OR m.sender_user_id IS NULL AND s.user_id=e.actor_user_id AND session_personal_audience(s))
   AND NOT EXISTS(SELECT 1 FROM decision_events reversal WHERE reversal.reverses_event_id=e.id);
  IF event_count<3 OR root_count<2 THEN RETURN false;END IF;
  IF EXISTS(SELECT 1 FROM decision_events support JOIN decision_events conflict
    ON conflict.workspace_id=support.workspace_id AND conflict.actor_user_id=support.actor_user_id
    AND conflict.event_kind='memory.observation_recorded' AND conflict.payload->>'claim'=support.payload->>'claim'
    JOIN decision_derivations d ON d.decision_event_id=conflict.id AND d.relation IN ('contradicts','invalidates')
    WHERE support.id::text IN(SELECT jsonb_array_elements_text(evidence_group))
    AND NOT EXISTS(SELECT 1 FROM decision_events reversal WHERE reversal.reverses_event_id=conflict.id)) THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END $$;

CREATE FUNCTION memory_learning_allows(value jsonb,context jsonb DEFAULT '{}',review boolean DEFAULT false,at_time timestamptz DEFAULT now()) RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE key text; required text;
BEGIN
 IF value IS NULL OR review THEN RETURN true; END IF;
 IF NOT memory_learning_evidence_allows(value) THEN RETURN false;END IF;
 IF jsonb_typeof(value->'applicability') IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(value->'applicability') AS allowed_key(name) WHERE allowed_key.name NOT IN ('projectId','taskId','operation','operationKey','activity','exceptionTo')) THEN RETURN false;END IF;
 IF value->>'version' IS DISTINCT FROM '1' OR coalesce(value->>'state','') NOT IN ('legacy','established') THEN RETURN false;END IF;
 IF nullif(value->>'appliesFrom','')::timestamptz>at_time OR nullif(value->>'appliesUntil','')::timestamptz<=at_time THEN RETURN false;END IF;
 FOREACH key IN ARRAY ARRAY['projectId','taskId','operation','operationKey','activity'] LOOP
  required:=value#>>ARRAY['applicability',key];
  IF required IS NOT NULL AND required IS DISTINCT FROM context->>key THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow THEN RETURN false;
END $$;

ALTER TABLE memory_verifications DROP CONSTRAINT memory_verifications_action_check;
ALTER TABLE memory_verifications ADD CONSTRAINT memory_verifications_action_check CHECK(action IN ('confirm','adjust_scope','adjust_sensitivity','edit_summary','edit_applicability','delete'));

-- Metadata is a canonical selected field, covered by the existing field authority.
CREATE OR REPLACE FUNCTION application_memory_field_keys() RETURNS text[]
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT ARRAY['id','assistant_id','user_id','app_id','workspace_id','scope','tags','summary','detail','confidence','sensitivity','compartments','project_ids','scope_version','scope_held','source','source_session_id','recall_count','useful_recall_count','last_recalled_at','created_at','updated_at','created_by_user_id','created_by_assistant_id','source_episode_id','verified_by_user_id','verified_at','valid_from','valid_to','superseded_by','retracted_at','retracted_reason','retracted_by','original_scope','original_sensitivity','original_summary','learning']::text[]
$$;

CREATE FUNCTION invalidate_memory_learning_change() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
BEGIN
 IF OLD.learning IS DISTINCT FROM NEW.learning THEN
  PERFORM hold_scope_descendants(OLD.workspace_id,'memory',OLD.id);
  NEW.scope_version:=GREATEST(NEW.scope_version,OLD.scope_version+1);
 END IF;
 RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION invalidate_memory_learning_change() FROM PUBLIC;
CREATE TRIGGER memory_learning_change BEFORE UPDATE OF learning ON memories
 FOR EACH ROW EXECUTE FUNCTION invalidate_memory_learning_change();
-- The only intentional existing helper change is the learning field in the canonical catalog.
UPDATE pg_temp.memory_learning_originals o SET expected_body=p.prosrc FROM pg_proc p
 WHERE p.oid=o.oid AND p.oid='public.application_memory_field_keys()'::regprocedure;
DO $controlled_repin$
<<controlled_repin>>
DECLARE previous record;caller record;body text;round integer;changed boolean;
BEGIN
 FOR round IN 1..64 LOOP
  changed:=false;
  IF EXISTS(SELECT 1 FROM pg_temp.memory_learning_originals o LEFT JOIN pg_proc p ON p.oid=o.oid
   WHERE p.oid IS NULL OR p.prosrc IS DISTINCT FROM o.expected_body OR (to_jsonb(p)-'prosrc') IS DISTINCT FROM o.metadata)
  THEN RAISE EXCEPTION 'memory_learning_authenticated_code_changed';END IF;
  FOR previous IN SELECT o.*,p.prosrc current_body,
   encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') current_fingerprint,
   encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') current_hash
   FROM pg_temp.memory_learning_originals o JOIN pg_proc p ON p.oid=o.oid WHERE o.body IS DISTINCT FROM p.prosrc
  LOOP
   FOR caller IN SELECT p.oid,p.prosrc FROM pg_proc p WHERE p.prokind='f' AND p.oid<>previous.oid AND
    (position(previous.quoted_body IN p.prosrc)>0 OR position(previous.fingerprint IN p.prosrc)>0 OR position(previous.body_hash IN p.prosrc)>0)
   LOOP
    IF NOT EXISTS(SELECT 1 FROM pg_temp.memory_learning_originals o WHERE o.oid=caller.oid AND o.expected_body=caller.prosrc)
    THEN RAISE EXCEPTION 'memory_learning_unauthenticated_pin_consumer: %',caller.oid::regprocedure;END IF;
    body:=replace(replace(replace(caller.prosrc,previous.quoted_body,quote_literal(previous.current_body)),previous.fingerprint,previous.current_fingerprint),previous.body_hash,previous.current_hash);
    IF body IS DISTINCT FROM caller.prosrc THEN
     EXECUTE replace(pg_get_functiondef(caller.oid),caller.prosrc,body);
     UPDATE pg_temp.memory_learning_originals SET expected_body=controlled_repin.body WHERE oid=caller.oid;
     changed:=true;
    END IF;
   END LOOP;
   UPDATE pg_temp.memory_learning_originals SET body=previous.current_body,quoted_body=quote_literal(previous.current_body),
    fingerprint=previous.current_fingerprint,body_hash=previous.current_hash WHERE oid=previous.oid;
  END LOOP;
  IF NOT changed THEN EXIT;END IF;
  IF round=64 THEN RAISE EXCEPTION 'memory_learning_pin_cycle';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_temp.memory_learning_originals o LEFT JOIN pg_proc p ON p.oid=o.oid
  WHERE p.oid IS NULL OR p.prosrc IS DISTINCT FROM o.expected_body OR (to_jsonb(p)-'prosrc') IS DISTINCT FROM o.metadata)
 THEN RAISE EXCEPTION 'memory_learning_successor_code_changed';END IF;
END $controlled_repin$;
DO $reference_rows$
